mapper.select:
SELECT d.id, d.name, d.category_id AS categoryId, d.price, d.image, d.description, d.status, d.update_time AS updateTime, c.name AS category_name, f.id AS flavor_id, f.name AS flavor_name, f.value AS flavor_value FROM sky_take_out.dish d LEFT JOIN sky_take_out.category c ON d.category_id = c.id LEFT JOIN sky_take_out.dish_flavor f ON f.dish_id = d.id
AND d.name LIKE CONCAT('%', #{name}, '%')
AND d.category_id = #{categoryId}
AND d.status = #{status}
ORDER BY d.create_time DESC

